package io.knowledgebrain.media;
import java.time.*;import java.util.*;import java.nio.file.*;import java.net.*;import java.net.http.*;import java.io.*;import java.security.*;import java.security.cert.*;import javax.net.ssl.*;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.web.server.ResponseStatusException;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_STORAGE_ORIGIN",matches=".+")
class MinioStorageIntegrationTest {
 SSLContext tls() throws Exception {var trust=KeyStore.getInstance(KeyStore.getDefaultType());trust.load(null,null);try(var in=Files.newInputStream(Path.of("/storage-trust/ca.crt"))){int n=0;for(var cert:CertificateFactory.getInstance("X.509").generateCertificates(in))trust.setCertificateEntry("ca"+n++,cert);}var factory=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());factory.init(trust);var tls=SSLContext.getInstance("TLS");tls.init(null,factory.getTrustManagers(),null);return tls;}
 int upload(HttpClient client,ObjectStorage.UploadForm form,byte[] bytes,String key) throws Exception {String boundary="brain-"+UUID.randomUUID();var body=new ByteArrayOutputStream();for(var field:form.fields().entrySet()){String value=field.getKey().equals("key") && key!=null?key:field.getValue();body.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+field.getKey()+"\"\r\n\r\n"+value+"\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));}body.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"upload\"\r\nContent-Type: application/octet-stream\r\n\r\n").getBytes());body.write(bytes);body.write(("\r\n--"+boundary+"--\r\n").getBytes());var request=HttpRequest.newBuilder(URI.create(form.url())).timeout(Duration.ofSeconds(15)).header("Content-Type","multipart/form-data; boundary="+boundary).POST(HttpRequest.BodyPublishers.ofByteArray(body.toByteArray())).build();return client.send(request,HttpResponse.BodyHandlers.discarding()).statusCode();}
 @Test void realPolicyChecksumImmutableDownloadAndPrivateBucket() throws Exception {
  String endpoint=System.getenv("BRAIN_TEST_STORAGE_ORIGIN");var storage=new MinioStorage(endpoint,endpoint,System.getenv("BRAIN_TEST_STORAGE_ACCESS_KEY"),System.getenv("BRAIN_TEST_STORAGE_SECRET_KEY"),"/storage-trust/ca.crt",Clock.systemUTC());assertThat(storage.ready()).as("Versioned private storage readiness").isTrue();var client=HttpClient.newBuilder().sslContext(tls()).followRedirects(HttpClient.Redirect.NEVER).build();byte[] bytes="%PDF-brain attachment".getBytes();String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));var ids=new UuidV7(Clock.systemUTC());var pending=new MediaStore.Info(ids.next(),ids.next(),"PENDING",1,"한글.pdf","application/pdf",bytes.length,sha,Instant.now(),null);var form=storage.upload(pending);
  assertThat(upload(client,form,bytes,"uploads/sealed/forbidden")).isEqualTo(403);assertThat(upload(client,form,new byte[bytes.length+1],null)).isGreaterThanOrEqualTo(400);assertThat(upload(client,form,new byte[bytes.length],null)).isBetween(200,299);assertThatThrownBy(()->storage.verifyAndSeal(pending)).isInstanceOf(ResponseStatusException.class);assertThat(upload(client,form,bytes,null)).isBetween(200,299);String version=storage.verifyAndSeal(pending);assertThat(version).isNotBlank().isNotEqualTo("null");var available=new MediaStore.Info(pending.mediaId(),pending.spaceId(),"AVAILABLE",2,pending.filename(),pending.mimeType(),pending.byteSize(),pending.sha256(),pending.createdAt(),Instant.now());var download=storage.download(new MediaStore.Stored(available,version));var request=HttpRequest.newBuilder(URI.create(download.url())).GET().build();var result=client.send(request,HttpResponse.BodyHandlers.ofByteArray());assertThat(result.statusCode()).isEqualTo(200);assertThat(result.body()).isEqualTo(bytes);assertThat(result.headers().firstValue("Content-Disposition").orElseThrow()).startsWith("attachment;");assertThat(result.headers().firstValue("Content-Type").orElseThrow()).isEqualTo("application/octet-stream");
  assertThat(upload(client,form,new byte[bytes.length],null)).isBetween(200,299);assertThat(client.send(request,HttpResponse.BodyHandlers.ofByteArray()).body()).isEqualTo(bytes);assertThat(client.send(HttpRequest.newBuilder(URI.create(endpoint+"/brain-media/uploads/sealed/"+pending.spaceId()+"/"+pending.mediaId())).GET().build(),HttpResponse.BodyHandlers.discarding()).statusCode()).isEqualTo(403);
 }
}
